/**
 * core/server-options.js
 *
 * Loads, validates and exposes `skymp/config/server-options.<env>.json`.
 *
 * Context: this file was generated by `Initialize-LocalConfig.ps1` and
 * documented in 112 lines of schema, but **no code read it**. Configuration
 * that seems to exist and does nothing is worse than missing configuration — someone
 * sets `permadeathEnabled`, nothing happens, and concludes the server is
 * buggy.
 *
 * ─── This module's principle ──────────────────────────────────────────────
 *
 * Only options that **actually change behavior today** go in here. Declaring the
 * 24 schema options and wiring 4 would recreate exactly the problem this
 * file exists to solve, only harder to notice — because then the
 * file *is* read, and people have less reason to be suspicious.
 *
 * Unimplemented options are listed in `DECLARED_BUT_UNWIRED` and the loader
 * warns at boot when it finds one of them. When you implement one, move it to
 * `SPEC` and take it off the list.
 *
 * Validation is strict and fails loudly: a value of the wrong type or out of range
 * aborts boot instead of falling back to a silent default. A mistyped gameplay
 * option that "almost works" is worse than a server that does not start.
 */

const fs = require('fs');
const path = require('path');

// ─────────────────────────────────────────────────────────────────────────────
// Spec of the WIRED options
// ─────────────────────────────────────────────────────────────────────────────

const num = (min, max) => ({ type: 'number', min, max });
const bool = () => ({ type: 'boolean' });

/**
 * Each entry is `'option.path': { ...rule, default, usedBy }`.
 * `usedBy` is not decorative: it is how someone finds where the option acts without
 * hunting through the repository.
 */
const SPEC = {
  'chat.whisperRange': { ...num(50, 5000), default: 450, usedBy: 'core/proximity-ranges.js (chat and voice)' },
  'chat.localRange': { ...num(50, 10000), default: 1200, usedBy: 'core/proximity-ranges.js (chat and voice)' },
  'chat.shoutRange': { ...num(50, 20000), default: 3500, usedBy: 'core/proximity-ranges.js (chat and voice)' },
  'chat.oocEnabled': { ...bool(), default: true, usedBy: 'rp-chat-service.js (/ooc)' },
  'chat.oocRateLimitSeconds': { ...num(0, 300), default: 5, usedBy: 'rp-chat-service.js (/ooc rate limit)' },

  'rp.permadeathEnabled': { ...bool(), default: false, usedBy: 'death-service.js (bleed-out retires instead of respawning)' },

  'spawn.playerRespawnSeconds': { ...num(0, 3600), default: 5, usedBy: 'death-service.js (RESPAWN_DELAY_MS)' },

  'economy.startingGold': { ...num(0, 1000000), default: 0, usedBy: 'whitelist.js (character starting gold)' },

  'profession.maxPerCharacter': { ...num(1, 20), default: 3, usedBy: 'profession-service.js (grantProfession/reactivateProfession)' },
  'profession.maxRank': { ...num(0, 20), default: 3, usedBy: 'profession-service.js (setProfessionRank)' },

  'mining.xpPerGather': { ...num(0, 1000), default: 2, usedBy: 'mining-service.js (registerMiningInteractions)' },
  'mining.maxDistance': { ...num(50, 1000), default: 200, usedBy: 'mining-service.js (registerMiningInteractions)' },
  'mining.cooldownMs': { ...num(1000, 3600000), default: 30000, usedBy: 'mining-service.js (registerMiningInteractions)' },

  'economy.largeTransactionThreshold': { ...num(1, 2147483647), default: 5000, usedBy: 'core/economy-service.js (_auditLargeTransfer)' },

  'depot.defaultCapacity': { ...num(1, 10000), default: 500, usedBy: 'core/depot-service.js (getOrCreateDepot)' },

  'crime.hotItemWindowMinutes': { ...num(1, 1440), default: 30, usedBy: 'core/crime-service.js (sweep: hot -> stolen)' },
  'crime.combatLogGraceMinutes': { ...num(1, 1440), default: 15, usedBy: 'core/crime-service.js (sweep: restitution after logging out with a hot item)' },
  'crime.sweepIntervalSeconds': { ...num(10, 3600), default: 60, usedBy: 'core/crime-service.js (initSweepTimer)' },

  'crafting.xpPerCraft': { ...num(0, 1000), default: 2, usedBy: 'crafting-service.js (craftItem)' },
  'crafting.signatureMinRank': { ...num(0, 20), default: 2, usedBy: 'crafting-service.js (craftItem — maker signature gate)' },
  'crafting.maxDistance': { ...num(50, 1000), default: 211, usedBy: 'crafting-service.js (interactions at a physical station)' },

  'publicWork.maxDistance': { ...num(50, 1000), default: 220, usedBy: 'public-work-service.js (quadro, origem e destino)' },
  'publicWork.sweepIntervalSeconds': { ...num(10, 3600), default: 60, usedBy: 'public-work-service.js (persistent expiry)' }
};

/**
 * Options that exist in the schema/example but do NOT do anything yet.
 * Keeping this list honest is the point of the whole module.
 */
const DECLARED_BUT_UNWIRED = [
  'rp.heavyRpEnabled',
  'rp.requireApprovedCharacterForSpawn', // whitelist.js always requires it already; the option would be to relax it
  'rp.allowRaceMenuBeforeApproval',
  'rp.defaultStartPointPolicy',
  'chat.logAllChannels',                 // rp-chat-service always logs already
  'staff.passwordAdminLoginEnabled',
  'staff.requireRolePermission',         // admin-service always requires it already
  'staff.requireCommandReason',          // only /permakill requires one today
  'staff.auditAllCommands',
  'staff.allowDestructiveCommandsInProduction',
  'spawn.vanillaSpawnMode',
  'spawn.npcRespawnSeconds',
  'spawn.disableRespawnActorIds',
  'economy.serverAuthoritativeCurrency', // always true by architecture already
  'economy.logAllTransactions',          // transaction-service always logs already
  'debug.enablePapyrusDebug',
  'debug.enableHotReload',
  'debug.enableDevTools'
];

// ─────────────────────────────────────────────────────────────────────────────

let _options = null;
let _warnings = [];

function getAtPath(obj, dottedPath) {
  return dottedPath.split('.').reduce((acc, key) => (acc == null ? undefined : acc[key]), obj);
}

/**
 * Validates a value against the rule. Returns an error message or `null`.
 */
function validateValue(dottedPath, value, rule) {
  if (rule.type === 'boolean') {
    if (typeof value !== 'boolean') return `${dottedPath}: expected boolean, got ${typeof value} (${JSON.stringify(value)})`;
    return null;
  }
  if (rule.type === 'number') {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      return `${dottedPath}: expected number, got ${typeof value} (${JSON.stringify(value)})`;
    }
    if (value < rule.min || value > rule.max) {
      return `${dottedPath}: ${value} is outside the allowed range [${rule.min}, ${rule.max}]`;
    }
    return null;
  }
  return `${dottedPath}: unknown type rule '${rule.type}'`;
}

/**
 * Loads the file for the current environment.
 *
 * A missing file is NOT an error: the server runs with the defaults, which are the
 * same values that were hardcoded before this module existed. What is an
 * error is a file that is present with invalid content — then someone tried to
 * configure something and deserves to know it did not work.
 *
 * @param {string} [environment] 'local' | 'staging' | 'production'.
 *   Default: NODE_ENV, or 'local'.
 */
function load(environment) {
  const env = environment || process.env.NODE_ENV || 'local';
  const configPath = path.resolve(__dirname, '..', '..', 'config', `server-options.${env}.json`);

  _warnings = [];
  const resolved = {};
  for (const [dottedPath, rule] of Object.entries(SPEC)) {
    resolved[dottedPath] = rule.default;
  }

  if (!fs.existsSync(configPath)) {
    _options = resolved;
    _warnings.push(`server-options.${env}.json not found — using defaults.`);
    return { ok: true, options: resolved, warnings: _warnings, path: configPath, usedFile: false };
  }

  let raw;
  try {
    raw = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch (err) {
    // Fail loudly: the file exists, so someone wanted to configure something.
    throw new Error(`[server-options] ${configPath} is not valid JSON: ${err.message}`);
  }

  const errors = [];
  for (const [dottedPath, rule] of Object.entries(SPEC)) {
    const value = getAtPath(raw, dottedPath);
    if (value === undefined) continue; // not provided: stays at the default
    const error = validateValue(dottedPath, value, rule);
    if (error) { errors.push(error); continue; }
    resolved[dottedPath] = value;
  }

  if (errors.length > 0) {
    throw new Error(
      `[server-options] ${configPath} has invalid values:\n  - ${errors.join('\n  - ')}\n` +
      `Fix the file or remove the keys to use the defaults.`
    );
  }

  // Warn about what the person configured thinking it would take effect.
  for (const dottedPath of DECLARED_BUT_UNWIRED) {
    if (getAtPath(raw, dottedPath) !== undefined) {
      _warnings.push(`${dottedPath} is in the file but does NOT do anything YET (see core/server-options.js).`);
    }
  }

  _options = resolved;
  return { ok: true, options: resolved, warnings: _warnings, path: configPath, usedFile: true };
}

/**
 * Reads an already-loaded option. Calls `load()` itself if nobody did before,
 * so a module does not depend on boot order.
 */
function get(dottedPath) {
  if (!_options) load();
  if (!(dottedPath in SPEC)) {
    throw new Error(`[server-options] '${dottedPath}' is not in SPEC. If you just implemented it, move it from DECLARED_BUT_UNWIRED to SPEC.`);
  }
  return _options[dottedPath];
}

/** Current state, for boot diagnostics. */
function describe() {
  if (!_options) load();
  return {
    wired: Object.keys(SPEC).length,
    unwired: DECLARED_BUT_UNWIRED.length,
    values: { ..._options },
    warnings: [..._warnings]
  };
}

/** Test only: discards the loaded state. */
function _reset() {
  _options = null;
  _warnings = [];
}

module.exports = { load, get, describe, SPEC, DECLARED_BUT_UNWIRED, _reset };
